#!/usr/bin/env python3
"""Turn ../firmware/src/ukraine_map.h (generated by gen_ukraine_map.py for the ESP32) into the
ESP8266 form: every table and string in PROGMEM (const data would otherwise sit in the 80 KB RAM),
read through the mapPt / mapRing / mapRegion / mapRaion accessors.

Usage: tools/map_progmem.py ../firmware/src/ukraine_map.h src/ukraine_map.h"""
import re
import sys

src, dst = sys.argv[1], sys.argv[2]
text = open(src, encoding="utf-8").read()
head, body = text.split("#ifdef UKRAINE_MAP_DEFINE\n", 1)
body = body.rsplit("#endif", 1)[0]

head = head.replace("#include <stdint.h>", "#include <Arduino.h>")
head = head.replace("// Generated by tools/gen_ukraine_map.py. Do not edit.",
                    "// Generated by tools/gen_ukraine_map.py and converted by tools/map_progmem.py (ESP8266: data in\n"
                    "// flash, read with the accessors below). Do not edit.")
head = head.replace("struct MapRegion { uint8_t firstRing, rings; const char *label; };",
                    "struct MapRegion { uint8_t firstRing, rings; const char *label; };  // label: PROGMEM")
head = head.replace("struct MapRaion { uint16_t firstRing; uint8_t rings, oblast; const char *key, *name, *alt; };",
                    "struct MapRaion { uint16_t firstRing; uint8_t rings, oblast; const char *key, *name, *alt; };  // strings: PROGMEM")
head += """
inline int16_t mapPt(int i, int c) { return (int16_t)pgm_read_word(&MAP_POINTS[i][c]); }
inline MapRing mapRing(int i) { MapRing r; memcpy_P(&r, &MAP_RINGS[i], sizeof r); return r; }
inline MapRegion mapRegion(int i) { MapRegion r; memcpy_P(&r, &MAP[i], sizeof r); return r; }
inline MapRaion mapRaion(int i) { MapRaion r; memcpy_P(&r, &RAION[i], sizeof r); return r; }
inline String mapLabel(int region) { return String(FPSTR(mapRegion(region).label)); }

"""

strings = {}
decls = []


def sym(s):
    if s not in strings:
        name = "MAP_S%d" % len(strings)
        strings[s] = name
        decls.append('static const char %s[] PROGMEM = "%s";' % (name, s))
    return strings[s]


def strs_to_syms(block):
    return re.sub(r'"((?:[^"\\]|\\.)*)"', lambda m: sym(m.group(1)), block)


body = body.replace("const int16_t MAP_POINTS[][2] = {", "const int16_t MAP_POINTS[][2] PROGMEM = {")
body = body.replace("const MapRing MAP_RINGS[] = {", "const MapRing MAP_RINGS[] PROGMEM = {")
i = body.index("const MapRegion MAP[MAP_REGIONS] = {")
tail = strs_to_syms(body[i:])
tail = tail.replace("const MapRegion MAP[MAP_REGIONS] = {", "const MapRegion MAP[MAP_REGIONS] PROGMEM = {")
tail = tail.replace("const MapRaion RAION[MAP_RAIONS] = {", "const MapRaion RAION[MAP_RAIONS] PROGMEM = {")
body = body[:i] + "\n".join(decls) + "\n" + tail

open(dst, "w", encoding="utf-8").write(head + "#ifdef UKRAINE_MAP_DEFINE\n" + body + "#endif\n")
print("map_progmem: %d strings" % len(strings))
